// ratelimit/bucket.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock provides the current time, enabling deterministic testing.
type Clock interface {
	Now() time.Time
}

// TokenBucket is a concurrency-safe token-bucket rate limiter.
type TokenBucket struct {
	mu       sync.Mutex
	clock    Clock
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
}

// NewTokenBucket creates a TokenBucket. capacity is the maximum burst size,
// rate is the sustained tokens-per-second refill rate. Both must be > 0.
func NewTokenBucket(clock Clock, capacity, rate float64) (*TokenBucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be > 0")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	return &TokenBucket{
		clock:    clock,
		capacity: capacity,
		rate:     rate,
		tokens:   capacity,
		last:     clock.Now(),
	}, nil
}

// AllowN attempts to consume n tokens. Returns true if the tokens were
// available and consumed, false otherwise.
func (tb *TokenBucket) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := tb.clock.Now()
	elapsed := now.Sub(tb.last).Seconds()
	tb.last = now

	tb.tokens += elapsed * tb.rate
	if tb.tokens > tb.capacity {
		tb.tokens = tb.capacity
	}

	need := float64(n)
	if tb.tokens >= need {
		tb.tokens -= need
		return true
	}
	return false
}

// Allow is shorthand for AllowN(1).
func (tb *TokenBucket) Allow() bool {
	return tb.AllowN(1)
}
