func TestNewTokenBucket_Validation(t *testing.T) {
	tests := []struct {
		name     string
		clock    Clock
		capacity float64
		rate     float64
		wantErr  bool
	}{
		{"nil clock", nil, 10, 1, true},
		{"zero capacity", &fakeClock{}, 0, 1, true},
		{"negative capacity", &fakeClock{}, -1, 1, true},
		{"zero rate", &fakeClock{}, 10, 0, true},
		{"negative rate", &fakeClock{}, 10, -1, true},
		{"valid", &fakeClock{}, 10, 1, false},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := NewTokenBucket(tc.clock, tc.capacity, tc.rate)
