func TestAllowN(t *testing.T) {
	tests := []struct {
		name     string
		capacity float64
		rate     float64
		advances []time.Duration
		n        int
		want     []bool
	}{
		{
			name:     "burst then drain",
			capacity: 5,
			rate:     1,
			advances: []time.Duration{0, 0, 0, 0, 0, 0},
			n:        1,
			want:     []bool{true, true, true, true, true, false},
		},
		{
			name:     "refill after drain",
			capacity: 3,
			rate:     1,
			advances: []time.Duration{0, 0, 0, 0, 2 * time.Second, 0},
			n:        1,
			want:     []bool{true, true, true, false, true, true},
		},
		{
			name:     "AllowN larger than capacity always fails",
			capacity: 5,
			rate:     10,
			advances: []time.Duration{0, 10 * time.Second},
			n:        6,
			want:     []bool{false, false},
		},
		{
			name:     "AllowN exact capacity",
			capacity: 5,
			rate:     1,
			advances: []time.Duration{0, 0},
			n:        5,
			want:     []bool{true, false},
		},
		{
			name:     "n zero always allowed",
			capacity: 1,
			rate:     1,
			advances: []time.Duration{0, 0},
			n:        0,
			want:     []bool{true, true},
		},
		{
			name:     "partial refill",
			capacity: 10,
			rate:     2,
			advances: []time.Duration{0, 500 * time.Millisecond, 500 * time.Millisecond},
			n:        1,
			want:     []bool{true, true, true},
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			fc := &fakeClock{t: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
			tb, err := NewTokenBucket(fc, tc.capacity, tc.rate)
			if err != nil {
				t.Fatal(err)
			}
			for i, adv := range tc.advances {
				fc.Advance(adv)
				got := tb.AllowN(tc.n)
				if got != tc.want[i] {
					t.Errorf("call %d: got %v, want %v", i, got, tc.want[i])
				}
			}
		})
	}
}

func TestAllowN_Concurrent(t *testing.T) {
	fc := &fakeClock{t: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
	tb, _ := NewTokenBucket(fc, 100, 10)

	done := make(chan bool, 200)
	for i := 0; i < 200; i++ {
		go func() { done <- tb.AllowN(1) }()
	}
	allowed := 0
	for i := 0; i < 200; i++ {
		if <-done {
			allowed++
		}
	}
	if allowed != 100 {
		t.Errorf("expected 100 allowed, got %d", allowed)
	}
}
