type TokenBucket struct {
	mu       sync.Mutex
	clock    Clock
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
}

// NewTokenBucket creates a TokenBucket. capacity must be > 0, rate must be > 0,
// and clock must not be nil.
func NewTokenBucket(clock Clock, capacity, rate float64) (*TokenBucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be > 0")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	return &TokenBucket{
		clock:    clock,
		capacity: capacity,
		rate:     rate,
		tokens:   capacity,
		last:     clock.Now(),
	}, nil
}

// AllowN reports whether n tokens can be consumed. If allowed, tokens are
// deducted. n must be >= 0.
func (tb *TokenBucket) AllowN(n float64) bool {
	if n < 0 {
		return false
	}
	tb.mu.Lock()
	defer tb.mu.Unlock()

